def _document_name(payload: Any) -> str:
    """The name on the identity document in a stored Didit event (same rule as the service)."""
    if not isinstance(payload, dict):
        return ""
    decision = payload.get("decision") if isinstance(payload.get("decision"), dict) else {}
    for container in (payload, decision):
        items: list[Any] = []
        many = container.get("id_verifications")
        if isinstance(many, list):
            items.extend(many)
        items.append(container.get("id_verification"))
        for item in items:
            if not isinstance(item, dict):
                continue
            full_name = item.get("full_name")
            if isinstance(full_name, str) and full_name.strip():
                return " ".join(full_name.split())[:255]
            parts = [
                str(item.get(key)).strip()
                for key in ("first_name", "last_name")
                if isinstance(item.get(key), str) and str(item.get(key)).strip()
            ]
            if len(parts) == 2:
                return " ".join(" ".join(parts).split())[:255]
    return ""


def backfill_names(apps: Any, schema_editor: Any) -> None:
    """Take the name from the newest stored Didit event of each case that carries one."""
    case_model = apps.get_model("kyc_compliance", "KycVerificationCase")
    event_model = apps.get_model("kyc_compliance", "KycProviderEvent")
    for case in case_model.objects.filter(verified_full_name="").iterator():
        for payload in (
            event_model.objects.filter(case_id=case.pk)
            .order_by("-processed_at", "-id")
            .values_list("raw_payload", flat=True)
            .iterator()
        ):
            name = _document_name(payload)
            if name:
                case_model.objects.filter(pk=case.pk).update(verified_full_name=name)
                break


